/**
 * THE ICON SET
 *
 * Forty engraved icons on one sheet, carried as an ALPHA MASK rather than a
 * picture: the game paints them with `currentColor`, so the same sheet is ink on
 * label stock, brass in a dark rail, and amber when a control is live. A
 * coloured sprite could not do that, and forty separate SVGs drift apart the
 * first time one is added.
 *
 * ORDER IS LOAD-BEARING, as with every sheet here: entry N is cell N, appended
 * only. The rows are the screens, the bench gauges, Supply's tabs and ingredient
 * kinds, the batch actions, and the almanac's weather.
 */
export const ICON_COLS = 8;
export const ICON_CELL = 128;

export type IconName =
  | 'supply'
  | 'hardware'
  | 'staff'
  | 'codex'
  | 'cellar'
  | 'orders'
  | 'archives'
  | 'save'
  | 'money'
  | 'renown'
  | 'reputation'
  | 'heat'
  | 'hygiene'
  | 'power'
  | 'slots'
  | 'season'
  | 'ingredients'
  | 'vessels'
  | 'books'
  | 'cultures'
  | 'underground'
  | 'substrate'
  | 'starter'
  | 'additive'
  | 'stir'
  | 'skim'
  | 'vent'
  | 'mist'
  | 'warm'
  | 'press'
  | 'filter'
  | 'seal'
  | 'sunny'
  | 'cloudy'
  | 'rain'
  | 'storm'
  | 'snow'
  | 'heatwave'
  | 'fog'
  | 'wind';

export const ICON_ORDER: IconName[] = [
  'supply', 'hardware', 'staff', 'codex', 'cellar', 'orders',
  'archives', 'save', 'money', 'renown', 'reputation', 'heat',
  'hygiene', 'power', 'slots', 'season', 'ingredients', 'vessels',
  'books', 'cultures', 'underground', 'substrate', 'starter', 'additive',
  'stir', 'skim', 'vent', 'mist', 'warm', 'press',
  'filter', 'seal', 'sunny', 'cloudy', 'rain', 'storm',
  'snow', 'heatwave', 'fog', 'wind',
];

